
const WORDS=[{"id": 0, "w": "急剧", "p": "jíjù", "t": "形容词", "m": "nhanh, nhanh chóng", "coll": "急剧变化、急剧增长", "s": "近几年，消费者的购物习惯发生了急剧变化。"}, {"id": 1, "w": "川流不息", "p": "chuānliú bùxī", "t": "成语", "m": "qua lại nườm nượp", "coll": "车辆川流不息、人群川流不息", "s": "节日期间，商场门前人群川流不息，十分热闹。"}, {"id": 2, "w": "登录", "p": "dēnglù", "t": "动词", "m": "đăng nhập", "coll": "登录账号、登录系统", "s": "购买商品之前，用户需要先登录账号，确认收货信息。"}, {"id": 3, "w": "指令", "p": "zhǐlìng", "t": "名词", "m": "chỉ thị, lệnh", "coll": "发出指令、执行指令", "s": "收到用户发出的指令后，系统立即开始处理订单。"}, {"id": 4, "w": "根深蒂固", "p": "gēnshēn dìgù", "t": "成语", "m": "thâm căn cố đế, ăn sâu bén rễ", "coll": "根深蒂固的观念、根深蒂固的习惯", "s": "一些根深蒂固的消费观念，不会因为技术变化就立刻消失。"}, {"id": 5, "w": "不免", "p": "bùmiǎn", "t": "副词", "m": "không tránh được", "coll": "不免担心、不免感到遗憾", "s": "第一次使用无人商店，他不免有些担心，便先阅读了说明。"}, {"id": 6, "w": "预言", "p": "yùyán", "t": "动词", "m": "tiên đoán, dự đoán", "coll": "预言未来、作出预言", "s": "有人预言，未来的商店将更加重视顾客的个性化体验。"}, {"id": 7, "w": "革命", "p": "gémìng", "t": "名词", "m": "cải cách triệt để", "coll": "技术革命、引发革命", "s": "新的支付方式给商业活动带来了一场深刻的革命。"}, {"id": 8, "w": "改良", "p": "gǎiliáng", "t": "动词", "m": "sửa đổi, cải tiến, cải thiện", "coll": "改良产品、改良设计", "s": "设计人员根据顾客的意见，不断改良产品，提高使用体验。"}, {"id": 9, "w": "欣欣向荣", "p": "xīnxīn xiàngróng", "t": "成语", "m": "thịnh vượng, phát đạt, phồn vinh", "coll": "欣欣向荣、欣欣向荣的景象", "s": "经过多年的发展，这座城市的商业呈现出欣欣向荣的景象。"}, {"id": 10, "w": "仓库", "p": "cāngkù", "t": "名词", "m": "kho, nhà kho", "coll": "仓库管理、进入仓库", "s": "工作人员在仓库里整理商品，为第二天的配送作准备。"}, {"id": 11, "w": "储备", "p": "chǔbèi", "t": "动词", "m": "dự trữ, trữ", "coll": "储备物资、储备资金", "s": "为了应对销售高峰，商家提前储备了足够的货物。"}, {"id": 12, "w": "结算", "p": "jiésuàn", "t": "动词", "m": "kết toán, thanh toán", "coll": "自动结算、结算费用", "s": "顾客选好商品以后，系统会自动结算费用，并显示购买清单。"}, {"id": 13, "w": "模式", "p": "móshì", "t": "名词", "m": "mô hình, kiểu, mẫu", "coll": "经营模式、服务模式", "s": "这家商店采用新的经营模式，让顾客能够随时了解商品信息。"}, {"id": 14, "w": "把手", "p": "bǎshou", "t": "名词", "m": "tay cầm, quai xách", "coll": "门的把手、握住把手", "s": "他握住门的把手，轻轻一拉，便走进了商店。"}, {"id": 15, "w": "装卸", "p": "zhuāngxiè", "t": "动词", "m": "bốc dỡ hàng hóa; tháo lắp", "coll": "装卸货物、装卸设备", "s": "清晨，工作人员正在仓库门口装卸货物。"}, {"id": 16, "w": "屏幕", "p": "píngmù", "t": "名词", "m": "màn hình", "coll": "触摸屏幕、屏幕显示", "s": "点击屏幕上的图标，顾客就可以查看商品的详细说明。"}, {"id": 17, "w": "相应", "p": "xiāngyìng", "t": "形容词", "m": "tương ứng, phù hợp", "coll": "相应措施、相应调整", "s": "面对需求的变化，商店及时采取了相应的措施。"}, {"id": 18, "w": "仪器", "p": "yíqì", "t": "名词", "m": "máy móc, thiết bị", "coll": "精密仪器、检测仪器", "s": "工作人员借助检测仪器，检查商品，是否符合相关要求。"}, {"id": 19, "w": "以免", "p": "yǐmiǎn", "t": "连词", "m": "để tránh", "coll": "以免遗忘、以免损坏", "s": "搬运这些设备时，请轻拿轻放，以免损坏内部零件。"}, {"id": 20, "w": "嫌", "p": "xián", "t": "动词", "m": "ghét, chê, không thích", "coll": "嫌麻烦、嫌价格高", "s": "他嫌办理手续太麻烦，后来才发现，其实几分钟就能完成。"}, {"id": 21, "w": "腥", "p": "xīng", "t": "形容词", "m": "tanh", "coll": "鱼腥味、味道腥", "s": "这条鱼闻起来有些腥，厨师便重新检查了保存情况。"}, {"id": 22, "w": "清理", "p": "qīnglǐ", "t": "动词", "m": "dọn dẹp, xử lý, thanh lý", "coll": "清理货架、清理库存", "s": "关门之前，店员认真清理货架，把商品重新摆放整齐。"}, {"id": 23, "w": "等候", "p": "děnghòu", "t": "动词", "m": "đợi, chờ", "coll": "耐心等候、等候通知", "s": "办理退货的顾客在服务台前耐心等候，工作人员逐一处理。"}, {"id": 24, "w": "性能", "p": "xìngnéng", "t": "名词", "m": "tính năng, chức năng", "coll": "性能稳定、产品性能", "s": "选购设备时，除了价格，还应该比较不同产品的性能。"}, {"id": 25, "w": "便利", "p": "biànlì", "t": "形容词", "m": "tiện lợi, thuận tiện", "coll": "交通便利、提供便利", "s": "在线查询服务为顾客提供了便利，也减少了反复咨询的时间。"}, {"id": 26, "w": "把关", "p": "bǎguān", "t": "动词", "m": "kiểm định", "coll": "严格把关、为质量把关", "s": "商品上市之前，企业应当严格把关，认真检查产品质量。"}, {"id": 27, "w": "人工", "p": "réngōng", "t": "名词", "m": "sức người, nhân công", "coll": "人工服务、人工操作", "s": "遇到系统无法解决的问题，顾客仍然可以选择人工服务。"}, {"id": 28, "w": "秤", "p": "chèng", "t": "名词", "m": "cái cân", "coll": "电子秤、一台秤", "s": "店员把水果放在秤上，确认重量后，再计算价格。"}, {"id": 29, "w": "运算", "p": "yùnsuàn", "t": "动词", "m": "tính toán", "coll": "自动运算、运算速度", "s": "这台设备能够自动运算，迅速算出所有商品的总价。"}, {"id": 30, "w": "总和", "p": "zǒnghé", "t": "名词", "m": "tổng số", "coll": "数量总和、价格总和", "s": "屏幕上显示的数字，就是这些商品价格的总和。"}, {"id": 31, "w": "着重", "p": "zhuózhòng", "t": "动词", "m": "nhấn mạnh, chú trọng", "coll": "着重说明、着重考虑", "s": "介绍新设备时，工作人员着重说明了操作中的注意事项。"}, {"id": 32, "w": "虚拟", "p": "xūnǐ", "t": "形容词", "m": "hư ảo, được tưởng tượng", "coll": "虚拟场景、虚拟空间", "s": "借助虚拟场景，顾客可以提前了解，家具摆进房间后的效果。"}, {"id": 33, "w": "投票", "p": "tóupiào", "t": "动词", "m": "bỏ phiếu, biểu quyết", "coll": "参加投票、投票决定", "s": "活动结束后，大家通过投票，选出了最受欢迎的设计。"}, {"id": 34, "w": "保管", "p": "bǎoguǎn", "t": "动词", "m": "bảo quản, giữ gìn, trông giữ", "coll": "妥善保管、保管物品", "s": "请妥善保管购物凭证，需要办理售后服务时，可以出示相关记录。"}, {"id": 35, "w": "新颖", "p": "xīnyǐng", "t": "形容词", "m": "mới mẻ, mới lạ", "coll": "设计新颖、款式新颖", "s": "这款产品设计新颖，刚一展出，就吸引了不少人的目光。"}, {"id": 36, "w": "羽绒服", "p": "yǔróngfú", "t": "名词", "m": "áo lông vũ", "coll": "一件羽绒服、穿羽绒服", "s": "天气转冷以后，她买了一件羽绒服，准备冬天出门时穿。"}, {"id": 37, "w": "旗袍", "p": "qípáo", "t": "名词", "m": "xường xám", "coll": "穿旗袍、一件旗袍", "s": "这件旗袍做工精细，上面的花纹，也十分雅致。"}, {"id": 38, "w": "中意", "p": "zhòngyì", "t": "动词", "m": "hợp ý, vừa ý", "coll": "十分中意、中意的款式", "s": "比较了几种颜色以后，她终于选到了，自己中意的款式。"}, {"id": 39, "w": "音响", "p": "yīnxiǎng", "t": "名词", "m": "dàn loa", "coll": "一套音响、音响设备", "s": "工作人员在演出开始前，仔细检查了，现场的音响设备。"}, {"id": 40, "w": "收音机", "p": "shōuyīnjī", "t": "名词", "m": "máy thu thanh, radio", "coll": "打开收音机、一台收音机", "s": "祖父打开收音机，坐在窗边，听起了熟悉的节目。"}, {"id": 41, "w": "水龙头", "p": "shuǐlóngtóu", "t": "名词", "m": "vòi nước", "coll": "关紧水龙头、更换水龙头", "s": "离开洗手间前，请确认已经，关紧水龙头。"}, {"id": 42, "w": "枚", "p": "méi", "t": "量词", "m": "cái, tấm", "coll": "一枚纽扣、一枚硬币", "s": "他从口袋里，拿出一枚硬币，放进了自动售货机。"}, {"id": 43, "w": "纽扣儿", "p": "niǔkòur", "t": "名词", "m": "nút áo, cúc áo", "coll": "缝纽扣儿、一颗纽扣儿", "s": "外婆拿起针线，把掉下来的纽扣儿，重新缝在衣服上。"}, {"id": 44, "w": "插座", "p": "chāzuò", "t": "名词", "m": "ổ điện, ổ cắm", "coll": "电源插座、墙上的插座", "s": "安装设备之前，他先检查了，墙上的电源插座。"}, {"id": 45, "w": "勘探", "p": "kàntàn", "t": "动词", "m": "thăm dò (để tìm quặng)", "coll": "勘探资源、地质勘探", "s": "研究团队根据已有资料，制定了，下一阶段的勘探计划。"}, {"id": 46, "w": "矿产", "p": "kuàngchǎn", "t": "名词", "m": "khoáng sản", "coll": "矿产资源、开发矿产", "s": "讨论矿产资源的利用时，既要考虑经济价值，也需要重视，对环境的影响。"}, {"id": 47, "w": "反馈", "p": "fǎnkuì", "t": "动词", "m": "phản hồi", "coll": "反馈意见、及时反馈", "s": "使用产品后，顾客可以通过页面，及时反馈自己的意见。"}, {"id": 48, "w": "款式", "p": "kuǎnshì", "t": "名词", "m": "kiểu dáng, kiểu, mẫu", "coll": "款式多样、选择款式", "s": "这家店提供多种款式，顾客可以按照自己的喜好选择。"}, {"id": 49, "w": "关怀", "p": "guānhuái", "t": "动词", "m": "quan tâm, chăm sóc", "coll": "关怀老人、亲切关怀", "s": "这项服务体现了，设计者对老年顾客，细致的关怀。"}, {"id": 50, "w": "无微不至", "p": "wúwēi búzhì", "t": "成语", "m": "tỉ mỉ chu đáo, từng li từng tí", "coll": "无微不至、无微不至的照顾", "s": "住院期间，她得到了家人，无微不至的照顾。"}, {"id": 51, "w": "需求", "p": "xūqiú", "t": "名词", "m": "nhu cầu", "coll": "满足需求、实际需求", "s": "改进服务之前，商家应该先了解，顾客的实际需求。"}, {"id": 52, "w": "主导", "p": "zhǔdǎo", "t": "名词／动词", "m": "vai trò chủ đạo; dẫn dắt, chi phối", "coll": "起主导作用、主导方向", "s": "在这次设计中，实际使用需求，始终起着，主导作用。"}, {"id": 53, "w": "兴隆", "p": "xīnglóng", "t": "形容词", "m": "phát đạt, hưng thịnh", "coll": "生意兴隆、商业兴隆", "s": "这家老店凭借良好的信誉，多年来，一直生意兴隆。"}];
